import{calculateSelectedStepPoolAmountsV3 as calculate}from'../../src/lib/results/selected-step-pool-amounts-v3.ts';
export const id=n=>`91000000-0000-4000-8000-${String(n).padStart(12,'0')}`,scope={actorId:id(1),tournamentId:id(2),eventId:id(3)};
export function source(){const paid=Array.from({length:17},(_,i)=>id(100+i));const policy={kind:'q',method:'q-graduated',feeMinor:1000,ratio:6,roundingUnitMinor:100},calculation=calculate({policy,paidCount:17,recipientCount:3});return{...scope,kind:'current-selected-step-pool-source-v3',status:'source_available',sourceDigest:'a'.repeat(64),ownershipRevisionId:id(4),qualificationResultVersionId:id(5),prizeSnapshotId:id(6),prizeDigest:'b'.repeat(64),liabilityScope:'optional_pools_only',refundPolicy:'no-pool-refunds-v1',directorReviewRequired:true,moneyMoved:false,payoutAuthorized:false,bankReceiptVerified:false,qMinor:17000,sideMinor:0,totalMinor:17000,prizePlan:{rounding:{qPool:'1',sidePool:'10'}},pools:[{poolId:id(7),label:'Q-Pool 1 - Graduated',kind:'q',operatingPolicyId:id(8),recipientReviewId:id(9),recipientSourceDigest:'c'.repeat(64),policy:{version:'selected-step-pool-policy-v3',...policy},paidParticipantIds:paid,calculation,recipients:paid.slice(0,3).map((participantId,i)=>({participantId,name:`Fictional Player ${i+1}`,tournamentPlayerId:`A-${i+1}`,amountMinor:calculation.awardsMinor[i]}))}]};}
export function review(){const s=source();return{kind:'selected-step-pool-review-v3',sourceDigest:s.sourceDigest,ownershipRevisionId:s.ownershipRevisionId,qualificationResultVersionId:s.qualificationResultVersionId,prizeSnapshotId:s.prizeSnapshotId,pools:s.pools.map(p=>({poolId:p.poolId,label:p.label,kind:p.kind,method:p.policy.method,ratio:p.policy.ratio,fundMinor:p.calculation.fundMinor,roundingUnitMinor:p.policy.roundingUnitMinor,recipients:p.recipients.map(({participantId,...r})=>r)})),qMinor:s.qMinor,sideMinor:s.sideMinor,totalMinor:s.totalMinor,directorReviewRequired:true,moneyMoved:false,payoutAuthorized:false};}
export function receipt(a){return{kind:'selected-step-pool-receipt-v3',status:a.request.kind==='selected-step-pool-save-v3'?'proposal_saved':'awards_recorded_unpaid',...scope,operationId:a.operationId,request:structuredClone(a.request),requestHash:'b'.repeat(64),revisionId:id(20),version:1,finalId:a.request.kind==='selected-step-pool-save-v3'?null:id(21),sourceDigest:a.review.sourceDigest,qMinor:a.review.qMinor,sideMinor:a.review.sideMinor,totalMinor:a.review.totalMinor,liabilityScope:'optional_pools_only',historicalReceipt:true,currentSourceVerified:false,moneyMoved:false,payoutAuthorized:false};}
export const reply=a=>({status:'accepted',attempt:structuredClone(a),receipt:receipt(a),reviewedSource:structuredClone(a.review)});
export function retained(){const values=new Map(),archives=[];return{values,archives,read:async k=>values.get(k)??null,transition:async(k,old,next,archive,signal)=>{if(signal?.aborted||(values.get(k)??null)!==old)return false;if(next===null)values.delete(k);else values.set(k,next);if(archive)archives.push(archive);return true;}};}
